import type {ArticleSection} from '../types/philosophy';

const section = (
  id: string,
  title: string,
  paragraphs: string[],
  relatedBranchIds?: string[],
  relatedPhilosopherIds?: string[],
  relatedWorkTitles?: string[],
): ArticleSection => ({id, title, paragraphs, relatedBranchIds, relatedPhilosopherIds, relatedWorkTitles});

export const editorialDepthBatch01BranchArticles: Record<string, ArticleSection[]> = {
  epistemology: [
    section('orientation', 'Knowledge is one success among many', [
      'Epistemology is philosophical inquiry into knowledge and the wider family of achievements and failures involved in trying to get things right. It asks when a belief is reasonable, what makes evidence relevant, how truth differs from confidence, and whether a person can know without being able to prove what they know. It also studies understanding, rationality, intellectual skill, ignorance, error, and responsible suspension of judgment. These questions concern ordinary acts such as recognizing a friend as well as scientific models, court testimony, historical reconstruction, and public trust in expertise.',
      'Knowledge is not identical to having a true belief. Someone who guesses a winning answer has reached the truth without knowing it, while a careful investigator can follow good evidence and still be mistaken. Justification names one kind of support that may make a belief rational or responsibly held; warrant is often used for whatever further positive status turns true belief into knowledge. Neither term has one agreed theory behind it. Some epistemologists emphasize reasons available to reflection, others reliable abilities or environments, and others the competent agency of the knower.',
      'Understanding adds another target. A student may memorize that a bridge collapsed without understanding how design, materials, weather, and maintenance interacted. Understanding seems to require grasping patterns, explanations, or dependencies, and it may sometimes survive small factual errors. Rationality is broader still: it can concern consistency, responsiveness to evidence, reasonable confidence, or good inquiry under limits. Epistemology therefore cannot be reduced to a single definition of propositional knowledge. It compares several epistemic goods and asks why they matter.',
    ], ['epistemology', 'philosophy-of-science'], [], []),
    section('histories', 'Many histories of reliable cognition', [
      'Questions now grouped under epistemology long predate the modern word. In classical Greek philosophy, Plato distinguishes knowledge from mere true judgment and asks what an account contributes, while Aristotle connects demonstrative knowledge with explanatory causes. Hellenistic Epicureans, Stoics, Academic skeptics, and Pyrrhonists dispute perception, criteria of truth, signs, and the proper response to disagreement. Medieval Jewish, Christian, and Islamic philosophers develop accounts of demonstration, testimony, illumination, prophecy, sense perception, and intellectual knowledge within institutions of commentary, law, theology, and science.',
      'Classical Indian debates make knowledge-generating processes, or pramāṇas, central. Nyāya, Buddhist, Mīmāṃsā, Jain, and other thinkers disagree over the authority and operation of perception, inference, testimony, comparison, and additional proposed sources. They also debate error, defeaters, self-awareness, the recognition that one knows, and whether a cognition is validated intrinsically or by something further. Dignāga and Dharmakīrti systematize influential Buddhist accounts of perception and inference, but they do not speak for every Buddhist school. Nyāya arguments likewise develop over centuries rather than forming one static doctrine.',
      'Chinese texts investigate knowing, discernment, naming, learning, testimony, cultivated attention, and the coordination of knowledge with action. Confucian, Mohist, Daoist, and later Buddhist and Neo-Confucian discussions do not merely restate a European question about justified true belief. Knowing how to conduct oneself, recognize a situation, use names well, and become perceptive through practice may be central. Comparison can illuminate recurring problems, but responsible comparison preserves differences among technical vocabularies, aims, genres, and social settings rather than forcing them into one universal taxonomy.',
    ], ['ancient-greek', 'skepticism', 'indian-philosophy', 'buddhist-epistemology', 'chinese-philosophy', 'islamic-philosophy'], ['plato', 'aristotle', 'dignaga', 'dharmakirti'], ['Theaetetus', 'Posterior Analytics']),
    section('sources', 'Perception, memory, inference, and self-knowledge', [
      'Perception seems to put a knower in contact with a world beyond thought, yet it is fallible and shaped by conditions, attention, concepts, and embodied capacities. Epistemologists ask whether experience itself justifies belief or whether only a belief can serve as a reason. They also dispute whether perception presents ordinary objects directly, represents them through mental content, or supports knowledge by functioning reliably. Illusion and hallucination test these accounts, but everyday success matters too: a theory that explains only exceptional error while making ordinary perception mysterious has paid a high price.',
      'Memory preserves knowledge and reasons across time, but it is not a neutral recording. Remembering can fade, reconstruct, combine, and be altered by later information. A person may retain knowledge after forgetting the evidence on which it was first based, raising questions about whether justification must always be presently accessible. Introspection creates parallel puzzles. People often know what they think, feel, or intend without observing themselves as outsiders, yet self-deception and unconscious influence limit claims of complete transparency. The authority of first-person judgment is real but neither simple nor unlimited.',
      'Inference extends knowledge beyond what is immediately perceived or remembered. Deduction aims to preserve truth from premises to conclusion; induction projects patterns to unobserved cases; abductive reasoning seeks the best explanation. Hume’s problem of induction asks how past regularities justify expectations about the future without assuming the very uniformity at issue. Contemporary accounts examine probability, explanatory virtues, causal models, and the reliability of inferential practices. Reason is therefore not a single source operating apart from experience: reasoning selects premises, uses learned concepts, and takes place within practices that can be trained or distorted.',
    ], ['empiricism', 'rationalism', 'philosophy-of-mind', 'philosophy-of-science'], ['hume'], ['An Enquiry Concerning Human Understanding']),
    section('testimony', 'Testimony, trust, expertise, and disagreement', [
      'Most human knowledge depends on other people. No individual verifies personally the existence of every city, the results of every experiment, the history of every institution, or the safety of every medicine. Testimony includes direct conversation, documents, instruments embedded in reporting systems, journalism, databases, and educational transmission. Reductionist approaches require independent reasons for trusting a speaker or practice; anti-reductionist approaches treat testimony as a basic source unless there are reasons for doubt. Both must explain how trust can be responsible without making hearers either gullible or impossibly self-sufficient.',
      'Expertise intensifies the problem because a layperson often cannot evaluate the expert’s first-order reasoning. Responsible deference can instead consider training, relevant track records, openness to criticism, agreement and disagreement among qualified communities, conflicts of interest, and the quality of institutions that check error. Credentials alone are not conclusive, and dissent alone does not reveal corruption. The central task is second-order judgment: deciding whom and which procedures to trust when direct mastery is unavailable. This is a normal condition of knowledge, not an embarrassing exception.',
      'Disagreement supplies evidence about one’s own fallibility. When an apparent epistemic peer reaches another conclusion from the same information, conciliationists argue that each side should reduce confidence to some degree; steadfast views allow greater persistence when one has independent reason to favor one’s assessment. Real disputes complicate the model because people rarely have exactly equal evidence, ability, or stakes. Deep disagreements may also concern which sources and methods count. Productive epistemology asks how inquiry can continue amid such conflict without pretending that compromise always tracks truth or that confidence proves independence.',
    ], ['epistemology', 'political-philosophy'], [], []),
    section('skepticism', 'What skeptical arguments test', [
      'Skepticism is a family of challenges rather than the single claim that nobody knows anything. A Cartesian-style argument asks whether ordinary evidence rules out dreams, deception, or a systematically misleading environment. A Pyrrhonian regress asks what justifies a reason: stopping may look arbitrary, circular support may look defective, and an endless chain may appear unusable. Humean skepticism challenges the rational basis of induction. Ancient skeptical practices may recommend suspension where arguments remain balanced, sometimes linking this discipline to tranquility rather than to a dogmatic denial of truth.',
      'Responses reject different steps. Foundationalists permit some non-inferentially justified beliefs; contextualists argue that standards for “knows” vary with conversational purposes; relevant-alternatives views require ruling out possibilities that matter in the context, not every imaginable error. Moorean replies treat ordinary knowledge as more secure than skeptical premises, while externalist theories allow reliable contact with truth even without a reflective refutation of deception. Kant’s strategy changes the question by investigating conditions under which an objective world can be experienced at all.',
      'No response simply makes fallibility disappear. If knowledge required eliminating every logically possible error, ordinary and scientific knowledge would be threatened. If standards are too permissive, lucky or irresponsible belief may count as knowledge. Skeptical arguments remain useful because they reveal assumptions about evidence, closure, relevance, and certainty. Their practical lesson is not permanent distrust. It is to distinguish live defeaters from merely describable possibilities and to match confidence to the quality of inquiry without confusing humility with indifference.',
    ], ['skepticism', 'rationalism'], ['descartes', 'hume', 'kant', 'pyrrho'], ['Meditations on First Philosophy']),
    section('structure', 'How justification is structured and accessed', [
      'The regress problem generates three prominent pictures of support. Foundationalism holds that some beliefs possess non-inferential justification and can support others. Contemporary foundations need not be infallible certainties; perceptual experience, memory, or rational insight might provide defeasible starting points. Coherentism emphasizes mutual support within a sufficiently integrated system of beliefs. Its challenge is the possibility of an internally coherent fantasy disconnected from reality. Infinitism allows an unending, nonrepeating chain of reasons, avoiding arbitrary stopping and circularity but raising questions about what finite thinkers must actually possess or be able to supply.',
      'Internalism and externalism concern a different division. Internalists hold, roughly, that a belief’s justification depends on factors within the thinker’s perspective, such as accessible reasons or mental states. This captures the intuition that epistemic responsibility should guide deliberation. Externalists allow status to depend on relations the believer may not recognize, such as a process being reliable in the actual environment. This captures children, skilled perceivers, and ordinary knowers who succeed without a theory of their reliability. Hybrid positions combine truth-conducive ability with perspective-sensitive competence.',
      'Reliabilism proposes that beliefs gain positive status through processes that tend to produce truth, but the relevant process must be specified carefully. “Seeing” may be reliable while “judging red objects at dusk” is not; choosing the description after the result risks circularity. Reliable clairvoyance cases test whether success without reasonable self-trust is enough. Conversely, an agent deceived in an environment indistinguishable from ours may reason impeccably while forming false beliefs. These cases expose several values hiding under “justification”: blamelessness, rational guidance, evidential support, and a dependable connection to truth may not always coincide.',
    ], ['epistemology'], [], []),
    section('knowledge-analysis', 'Gettier, reliability, virtue, and context', [
      'The justified-true-belief framework became influential because truth, belief, and justification each appear necessary for propositional knowledge. Plato’s Theaetetus examines true judgment with an account, but it neither simply states nor endorses the later formula, and many traditions organize inquiry differently. In 1963 Edmund Gettier presented compact cases in which a person has a justified true belief only because one error is accidentally offset by another fact. The lesson is not that all epistemology reduces to puzzles. It is that a favorable relation between reasons and truth must exclude certain forms of epistemic luck.',
      'Proposed repairs include requiring that no false premise do essential work, that belief track truth across relevant possibilities, that it be safe from easily being false, or that it arise through a reliable process. Each proposal faces counterexamples or difficult questions about which alternatives matter. Some philosophers treat knowledge as a basic concept rather than something analyzable into more elementary parts. Contextualists examine how ordinary knowledge attributions shift with practical and conversational standards, while invariantists seek one stable semantic standard even if the rationality of assertion or action varies.',
      'Virtue epistemology shifts attention toward intellectual agents and their excellences. On competence-based versions, knowledge is true belief attributable to a reliable cognitive ability; character-oriented versions emphasize traits such as intellectual courage, humility, conscientiousness, and open-mindedness. Virtues can explain why knowing is creditable and why inquiry has ethical dimensions, but traits are shaped by environments and institutions. A diligent investigator with corrupted data may fail, while a well-designed team can outperform isolated brilliance. The approach therefore leads naturally from individual ability to social conditions for intellectual flourishing.',
    ], ['analytic-philosophy', 'epistemology'], ['plato'], ['Theaetetus', 'Is Justified True Belief Knowledge?']),
    section('methods', 'Naturalized, formal, and scientific epistemology', [
      'Naturalized epistemology argues that accounts of knowledge and inquiry should engage empirical work on perception, cognition, development, language, and social behavior. Strong versions replace a traditional project of a priori justification with the study of how beliefs are actually formed; cooperative versions retain normative questions while using science to answer them responsibly. Critics worry that describing how people believe cannot by itself explain how they ought to believe. Naturalists reply that norms intended for human knowers must take actual capacities, environments, and correctable failure modes seriously.',
      'Formal epistemology uses logic, probability, decision theory, and computational models to represent belief and evidence. Bayesian approaches model degrees of confidence and rules for updating them, making explicit how surprising evidence can confirm a hypothesis. Formal tools also study belief revision, knowledge in groups, information flow, and disagreement. Their precision exposes hidden assumptions, but idealized agents with complete probability assignments and unlimited computation are not ordinary people. The philosophical task includes deciding which idealizations clarify rationality and which conceal the very constraints that inquiry must manage.',
      'Scientific knowledge is simultaneously empirical, inferential, historical, and collective. Instruments require calibration; data depend on classification and background theory; replication and peer criticism distribute error-checking across communities. Values can influence which questions receive attention, what risks count as acceptable, and how uncertainty is communicated without making every result a political preference. Understanding science epistemically means examining evidence and models as well as funding, publication, disciplinary diversity, and public institutions. Collective success can exceed any member’s comprehension, yet responsibility cannot be assigned to an abstract community without examining its practices.',
    ], ['philosophy-of-science', 'analytic-philosophy'], ['quine'], []),
    section('power', 'Social position, injustice, ignorance, and institutions', [
      'Social epistemology studies how knowledge is generated, transmitted, preserved, and damaged through relations among people. Feminist epistemologies reject the image of a generic knower without history or social location. Situatedness does not mean that every perspective is equally accurate or sealed inside itself. It means that access, interests, training, embodiment, and power can affect what evidence becomes visible and whose questions are pursued. Standpoint theories, feminist empiricisms, and other approaches disagree about objectivity, but they share attention to the social organization of inquiry.',
      'Epistemic injustice names wrongs done to people in their capacity as knowers. Testimonial injustice occurs when prejudice distorts credibility; hermeneutical injustice concerns unequal resources for making significant experience intelligible. Later work expands, revises, and criticizes these categories. An epistemology of ignorance examines not only missing information but patterns by which institutions preserve not-knowing, suppress inconvenient evidence, or make some facts costly to recognize. Ignorance can be produced through segregation, incentives, selective archives, professional norms, or repeated demands that marginalized people educate dominant groups.',
      'Institutional design is therefore epistemic as well as political. Courts, newsrooms, laboratories, archives, schools, platforms, and public agencies decide who may speak, what gets recorded, how challenges are heard, and when correction is rewarded. Diversity can improve inquiry when it brings genuinely different evidence and critical perspectives into conditions where dissent has standing; representation without influence is insufficient. Digital systems add scale and opacity: ranking can simulate consensus, synthetic media can detach claims from accountable speakers, and engagement incentives can favor certainty over correction. Better individual habits help, but they cannot substitute for trustworthy structures.',
    ], ['feminist-philosophy', 'political-philosophy', 'ethics'], [], ['Epistemic Injustice']),
    section('open-questions', 'What remains unsettled and how to keep exploring', [
      'Major questions remain open. Must knowledge be belief, and can groups or artificial systems know? Is understanding more valuable than knowledge, and does it require truth in the same way? How should evidence change confidence when people have limited time, unequal access, or conflicting values? Can an account of epistemic rationality be both demanding enough to criticize bias and realistic enough for finite agents? How do intellectual duties change when inquiry is collective? Disagreement about these questions reflects competing ideas of what epistemology should accomplish: conceptual analysis, practical guidance, explanation of success, or reform of institutions.',
      'A useful reading route alternates historical texts with contemporary problems. Plato’s Theaetetus introduces the difficulty of distinguishing knowledge from true judgment without supplying a final formula. Descartes and Hume dramatize different skeptical pressures; selections from Nyāya and Buddhist pramāṇa debates reveal other highly technical organizations of perception, inference, testimony, and error. Gettier’s essay then makes sense as one episode within a much wider history. Work on testimony, understanding, feminist epistemology, and epistemic injustice shows why the isolated believer cannot remain the field’s only model.',
      'For any theory, ask four questions. Which epistemic good does it explain: truth, knowledge, justification, understanding, responsible belief, or successful inquiry? What kind of agent and environment does it assume? Which errors can it diagnose, and what corrections does it recommend? Finally, who or what disappears from its picture of knowing? Epistemology is strongest when it joins conceptual care to fallible practice. It should help people inquire better while preserving the distinction between confidence and truth, between an honest method and guaranteed success, and between individual responsibility and institutional power.',
    ], ['epistemology', 'buddhist-epistemology', 'feminist-philosophy'], ['plato', 'descartes', 'hume', 'dignaga', 'dharmakirti'], ['Theaetetus', 'Meditations on First Philosophy', 'An Enquiry Concerning Human Understanding', 'Epistemic Injustice']),
  ],
  ethics: [
    section('orientation', 'Action, character, value, and shared life', [
      'Ethics is philosophical inquiry into how to act, what to value, what kind of character to cultivate, and which relationships and institutions make a life go better or worse. It asks about obligations and permissions, but it is not only a rulebook. Questions about friendship, grief, work, disability, punishment, technology, political power, and the treatment of nonhuman life involve emotion, social practice, material conditions, and competing pictures of a worthwhile life. Ethical reflection moves between individual choices and the structures that shape which choices are available.',
      'Several overlapping areas organize the field. Normative ethics develops standards for action, character, and institutions. Metaethics studies what moral judgments mean, whether and how they can be true, and how values give reasons. Moral psychology examines motivation, emotion, intention, habit, freedom, and responsibility. Applied ethics addresses domains such as medicine, war, environment, business, data, and artificial intelligence. Social and political philosophy investigates justice and legitimate power. These divisions are useful for navigation, but no wall keeps them apart: a theory of obligation rests on assumptions about agency, knowledge, and social life.',
      'Ethical theories often begin from different moral phenomena. Harm demands attention to consequences; promises make duties visible; courage and cruelty direct attention to character; caregiving reveals dependency; protest exposes unjust institutions; remorse shows that an act can matter beyond its external result. A theory gains clarity by emphasizing some of these, but it risks distorting the field if it treats one phenomenon as exhaustive. Ethical inquiry tests principles against cases, revises descriptions of cases in light of principles, and asks whose experience the starting point leaves out.',
    ], ['ethics', 'political-philosophy'], [], []),
    section('histories', 'Plural histories of ethical reflection', [
      'In ancient Greek traditions, Socratic questioning, Platonic accounts of justice, Aristotelian flourishing, and Hellenistic ways of life connect reasoning with formation of character. Yet ethics does not have one birthplace or a single route toward modern theory. Jewish, Christian, and Islamic philosophers join virtue, law, intention, community, divine command, natural reason, and practices of interpretation in changing combinations. Their ethical arguments develop within legal, theological, medical, commercial, and political institutions rather than in isolation from them.',
      'Classical Chinese traditions debate how ritual, humaneness, standards, cultivated emotion, social role, and government shape good conduct. Confucian thinkers disagree over human tendencies and the work of education; Mohists criticize inherited partiality through standards of benefit and inclusive concern; Daoist texts question rigid distinctions and forced projects. It is misleading simply to relabel each position as a local version of a contemporary European theory. Their terms connect personal cultivation, family relationship, language, and political order in distinctive ways, and the traditions remain internally disputed.',
      'South Asian traditions investigate dharma, action, consequence, liberation, discipline, nonviolence, intention, compassion, and the standing of living beings across Hindu, Buddhist, Jain, and other debates. Buddhist ethics connects the reduction of suffering with attention, motivation, precepts, wisdom, and compassion, while Jain traditions develop demanding disciplines of nonviolence. Philosophers working from African traditions have examined character, personhood, reciprocity, community, and the common good, while disputing romantic claims that either erase cultural plurality or subordinate individuals entirely to groups. Comparison should multiply questions, not arrange cultures as decorative answers around a default canon.',
    ], ['ancient-greek', 'chinese-philosophy', 'indian-philosophy', 'buddhist-philosophy', 'jainism', 'islamic-philosophy'], ['socrates', 'aristotle', 'confucius', 'mencius', 'mozi', 'buddha', 'mahavira'], ['Nicomachean Ethics', 'Analects']),
    section('reasons-value', 'Reasons, value, obligation, and judgment', [
      'A reason for action counts in favor of doing something, but philosophers disagree over what grounds reasons. Some begin with value: suffering gives reason to prevent it because suffering is bad. Reasons-first views explain value through what there is reason to desire, protect, or admire. Desire-based accounts connect reasons to an agent’s motivations under suitable reflection, while objectivist accounts allow reasons a person does not yet want to follow. The dispute matters whenever good advice challenges present desire, or when paternalism claims to know another person’s good.',
      'Value can be intrinsic or instrumental, agent-neutral or connected to particular relationships, commensurable or resistant to a single scale. Well-being may involve pleasure, desire satisfaction, objective goods, capabilities, meaningful activity, or some plural combination. Obligation concerns what must be done; permission concerns what is allowed; supererogation concerns admirable action beyond duty. Rights may protect choices, interests, status, or forms of relationship. These concepts overlap without collapsing into one another: producing more value does not automatically settle whether a right may be infringed or whether a special obligation has been betrayed.',
      'Ordinary judgment is neither raw intuition nor automatic application of theory. People notice salient features through habits, emotions, concepts, and social narratives. Particularists argue that a consideration’s moral significance can change across contexts, while generalists defend principles capable of guiding and explaining judgment. Reflective equilibrium seeks coherence among considered judgments, principles, and background theories through mutual revision. Critics ask which judgments count as “considered” when bias and unjust convention shape perception. Ethical method therefore includes learning to redescribe a case and to hear testimony that changes what the case is understood to be.',
    ], ['ethics', 'epistemology'], [], []),
    section('consequences', 'Consequences, welfare, and demandingness', [
      'Consequentialist theories assess choices by the value of outcomes. Classical utilitarianism makes aggregate well-being central and insists that each affected person’s welfare count. This exposes the moral importance of neglected suffering and makes institutions answerable to their actual effects. Consequentialism is a family, not one formula: theories differ about whether they evaluate acts, rules, motives, or institutions; whether value is pleasure, preference satisfaction, objective goods, or a plurality; and whether distribution, equality, and priority for the worse off matter independently.',
      'The approach faces objections about justice, integrity, and demandingness. Maximizing aggregate good may appear to permit harming one person for a larger benefit, to treat commitments as replaceable, or to require constant sacrifice whenever resources could help more elsewhere. Consequentialists respond with indirect rules, agent-relative options, richer theories of value, and attention to the long-term consequences of stable rights and trust. Critics reply that a right should not depend entirely on whether honoring it happens to maximize value. The disagreement turns partly on whether moral constraints are independent sources of reasons or essential components of good outcomes.',
      'Consequences remain unavoidable even for opponents of consequentialism. A rule followed without attention to predictable harm can become moral evasion, and institutions must compare policies under uncertainty. Conversely, forecasting is vulnerable to bias, incomplete data, and unequal control over whose losses count. Population ethics and climate policy add distant people, future generations, and uncertain catastrophes. The important question is not whether effects matter, but how they matter alongside rights, relationships, responsibility, and fair procedures—and who bears risk when decision makers are wrong.',
    ], ['utilitarianism', 'ethics'], ['bentham', 'mill', 'derek-parfit'], ['An Introduction to the Principles of Morals and Legislation', 'Utilitarianism']),
    section('duties-agreement', 'Duties, rights, contracts, and justifiability', [
      'Deontological theories hold that some choices are required or forbidden in ways not reducible to producing the best total outcome. Kantian ethics grounds obligation in rational autonomy and asks whether principles of action can be willed as universal law. Treating persons as ends requires respect for their capacity to set and pursue purposes. Other deontological views begin with rights, special relationships, divine commands, or plural duties such as fidelity, reparation, gratitude, and noninjury. Deontology therefore is not synonymous with one rigid list or with ignoring consequences.',
      'Duties can conflict, and rules require interpretation. A prohibition on deception may meet a duty to protect someone from violence; respect for autonomy may conflict with care for a person whose decision-making capacity is impaired. Threshold views allow catastrophic consequences to override ordinary constraints, while absolutist positions deny some tradeoffs altogether. Critics argue that deontology may fetishize clean hands when refusal still permits preventable harm. Defenders answer that agency matters: doing, intending, allowing, and using another person as a means can have different moral significance even when outcomes resemble each other.',
      'Contractarian and contractualist approaches ask what principles people could agree to, but the labels identify different projects. Contractarian theories often model mutually advantageous cooperation among agents pursuing their interests. Contractualist theories emphasize principles that persons regarded as free and equal could not reasonably reject. Both face questions about bargaining power, disability, dependency, nonhuman animals, and future people who cannot participate in an actual agreement. The idea of agreement is ethically useful only if the conditions of justification do not reproduce the exclusions that the procedure is supposed to test.',
    ], ['deontology', 'political-philosophy'], ['kant', 'rawls'], ['Groundwork of the Metaphysics of Morals', 'A Theory of Justice']),
    section('virtue-care', 'Virtue, care, relationship, and dependency', [
      'Virtue ethics asks what dispositions enable good action and a flourishing life. Aristotle’s account joins habituation, emotion, practical wisdom, friendship, political community, and external goods. Contemporary virtue ethics includes neo-Aristotelian, exemplarist, agent-based, and plural approaches, and virtue language also appears in Confucian, Buddhist, African, and other traditions with different metaphysical and social commitments. A virtue is not merely a socially praised habit. Courage, for example, must be distinguished from reckless confidence, and practical wisdom is needed to recognize what a situation calls for.',
      'Objections ask whether virtue ethics gives determinate guidance, whether ideals of flourishing exclude people whose lives do not fit inherited models, and whether character is as stable across situations as theories assume. Virtue ethicists answer that no decision procedure eliminates judgment and that action guidance can refer to what honesty, justice, or compassion requires. Social critics add that character is enabled or obstructed by institutions: exhorting an exhausted caregiver to become more generous may conceal an unjust allocation of labor. Good character cannot repair every bad structure.',
      'Care ethics begins from vulnerability, interdependence, and the moral work of attending and responding to particular others. It asks who performs care, whose dependency is visible, and how caring practices are supported or exploited. Care is not sentimental benevolence or a license for self-erasure; it can require competence, boundaries, political organization, and resistance to domination. Feminist ethics broadens these questions by examining gender, race, class, sexuality, disability, embodiment, and power across every area of ethics. Justice and care are not exclusive alternatives: fair institutions require care, and relationships require protection from unequal power.',
    ], ['virtue-ethics', 'feminist-philosophy', 'confucianism'], ['aristotle', 'confucius', 'iris-murdoch', 'philippa-foot'], ['Nicomachean Ethics']),
    section('agency', 'Intention, motivation, freedom, and moral luck', [
      'Moral psychology asks how judgment becomes action. Knowing that something is wrong does not guarantee resistance to fear, habit, appetite, loyalty, or social pressure. Internalists about moral motivation connect sincere judgment necessarily or normally with motivation; externalists allow a gap requiring an independent desire. Emotion may disclose value, distort attention, or do both. Accounts of weakness of will, self-deception, implicit bias, and identity show why ethical agency is neither pure reasoning nor mechanical response. Cultivation and institutional support can matter as much as a moment of choice.',
      'Intention helps distinguish accidents, side effects, negligence, and purposeful harm. The doctrine of double effect and related debates ask whether intending harm differs from foreseeing it, while critics question whether descriptions of intention can be manipulated to excuse wrongdoing. Responsibility also raises the free-will problem: must an agent have been able to do otherwise, or is acting from reasons-responsive capacities enough? Practices of blame involve standing, relationship, communication, and repair as well as metaphysical freedom. Punishment cannot be justified merely by labeling someone responsible.',
      'Moral luck appears when judgment depends on factors outside an agent’s control. Two equally careless drivers may be judged differently if only one happens to encounter a pedestrian. Upbringing, opportunity, consequences, and the situations one faces all contain luck, threatening the intuition that people should be assessed only for what they control. Responses restrict responsibility, revise the control principle, or distinguish blameworthiness from regret and remedial duties. Structural injustice adds another layer: people can participate in harmful systems without intending the total outcome, yet denying all responsibility leaves durable harms without agents of change.',
    ], ['ethics', 'philosophy-of-mind'], ['anscombe', 'thomas-nagel'], ['Intention']),
    section('metaethics', 'What moral claims mean and what could make them true', [
      'Metaethics examines the metaphysical, semantic, epistemological, and psychological commitments of moral thought. Moral realists hold that at least some moral claims are true independently of anyone’s endorsement, though they disagree about whether moral facts are natural facts or irreducibly normative. Antirealist positions include error theories, which say ordinary moral claims systematically fail, and noncognitivist or expressivist views, which emphasize the practical attitudes voiced by moral language. Sophisticated expressivism still must explain disagreement, inference, consistency, and the apparent objectivity of moral argument.',
      'Constructivist theories ground normative authority in procedures or standpoints of practical reasoning rather than in an independent realm of moral objects. Relativist views connect truth or justification to cultures, frameworks, or perspectives, but cultural variation alone does not establish relativism. Persistent disagreement also challenges realism without refuting it: disagreement may result from factual error, interests, power, or the difficulty of the subject. Realists owe an account of moral knowledge; antirealists owe an account of criticism that is more than clashing preference. No simple appeal to tolerance resolves these disputes.',
      'Metaethics matters in practice because it changes how reasons, reform, and error are understood, but practical agreement does not require settling every second-order question. A realist and an expressivist may both condemn torture while explaining the judgment differently. Conversely, shared metaethics does not guarantee agreement about cases. Moral epistemology asks how experience, emotion, testimony, principles, and social position justify ethical belief. It must confront the danger of status-quo bias without assuming that novelty is insight. Confidence in moral judgment should remain answerable to reasons and to those who live under its consequences.',
    ], ['ethics', 'epistemology', 'analytic-philosophy'], [], []),
    section('institutions', 'Power, institutions, collective responsibility, and global justice', [
      'Wrongdoing is not always a sequence of isolated bad choices. Laws, markets, borders, workplaces, families, and technical systems distribute authority, vulnerability, opportunity, and risk. A formally neutral rule can reproduce inequality when applied to unequal circumstances. Structural analysis asks how ordinary compliant actions combine into patterns of domination or deprivation. This does not make individual agency irrelevant; it changes the question from locating one villain to identifying roles, benefits, capacities, histories, and coordinated reforms. Ethical responsibility can be backward-looking, forward-looking, shared, or institutional.',
      'Collective responsibility is controversial because a corporation, state, or movement may act through decision procedures that no single member controls, while indiscriminate group blame can punish people who neither caused nor endorsed a harm. Philosophers distinguish responsibility of an organized collective from shared responsibility among members and from individual complicity. Remedies may depend on causal contribution, benefit, capacity, role, or fair distribution of burdens. Each criterion has limits. Those most able to help did not necessarily cause the problem, but causal responsibility alone may be impossible to trace or insufficient for repair.',
      'Global justice asks what people and institutions owe across borders. Poverty, migration, trade, war, public health, colonial histories, and climate change challenge theories designed around a self-contained state. Universal principles can expose parochial privilege, yet their application must not erase political agency or local knowledge. Particular relationships and historical responsibilities can generate duties beyond general humanitarian concern. Ethical inquiry here meets political feasibility: an ideal detached from power may guide criticism but fail to explain transition, while realism without normative standards can rename entrenched injustice as necessity.',
    ], ['political-philosophy', 'ethics'], ['rawls', 'angela-davis'], []),
    section('applied', 'Bodies, environments, technologies, and future beings', [
      'Bioethics examines consent, capacity, disability, reproduction, public health, research, scarce resources, and the goals of medicine. Principles such as autonomy, beneficence, nonmaleficence, and justice are starting points rather than an algorithm. A consent form cannot correct coercive circumstances, and aggregate health gains can conceal who bears risk. Disability ethics challenges assumptions that dependence or bodily difference automatically diminish a life’s value. Care, testimony, institutional trust, and distributive justice therefore belong inside clinical reasoning, not outside it as optional social context.',
      'Environmental ethics asks about the value and moral standing of animals, species, ecosystems, landscapes, and future generations. It challenges anthropocentrism and the idea that nature matters only as a resource, while also examining environmental racism, poverty, labor, land, and political power. Climate change joins cumulative causation, deep uncertainty, intergenerational harm, and unequal vulnerability. Individual consumption choices have significance, but infrastructure and policy organize their effects. Indigenous philosophies can inform environmental thought when engaged through specific thinkers, nations, and scholarship, not invoked as a single timeless ecological worldview.',
      'Technology ethics concerns design, deployment, ownership, labor, surveillance, manipulation, and the redistribution of responsibility. Artificial intelligence raises familiar issues at unusual scale: biased classification, opaque decisions, privacy, automation, environmental cost, concentration of power, and uncertainty about human oversight. Speculation about future machine agency does not cancel present duties toward people affected by current systems. Ethical evaluation must be empirically informed because a fictional account of how a system works cannot ground sound judgment. It must also ask which futures are being optimized, by whom, and who can contest the answer.',
    ], ['ethics', 'political-philosophy', 'philosophy-of-mind'], [], []),
    section('method', 'Pluralism, criticism, and a route into ethical inquiry', [
      'Ethical pluralism can mean that several kinds of value are real, that no single decision procedure captures them, or simply that multiple theories deserve comparison. It need not mean every judgment is equally sound. Monists argue that apparent plurality can be explained by one fundamental principle; pluralists worry that reduction loses friendship, justice, beauty, care, or integrity. Universalists seek norms applying across relevantly similar cases, while particularists emphasize context-sensitive reasons. The dispute is most useful when it clarifies how conflict is handled rather than assigning each thinker to a team.',
      'Criticism should test both a theory’s logic and its social imagination. Ask what it treats as morally basic, how it describes agency, whose suffering it notices, what information it requires, and which institutions would make its guidance possible. Look for counterexamples, but also ask whether the intuition driving a counterexample reflects prejudice or an unjust convention. Compare ideal and nonideal theory: a picture of fully compliant agents may reveal a standard, while attention to domination, scarcity, and strategic behavior may reveal what change actually demands.',
      'A beginner can enter through contrasting works without reducing the field to three European schools. Aristotle clarifies flourishing and practical wisdom; Kant sharpens autonomy and respect; Mill makes welfare and impartial consideration difficult to ignore. Add Confucian texts on ritual and cultivated relationship, Buddhist work on intention and suffering, feminist and care ethics on dependency and power, and African philosophical discussions of personhood and community. Then choose a concrete problem and let it pressure every framework. The goal is not a slogan that solves all cases, but more accountable judgment about how people, institutions, and forms of life can become less harmful and more just.',
    ], ['ethics', 'virtue-ethics', 'deontology', 'utilitarianism', 'feminist-philosophy'], ['aristotle', 'kant', 'mill', 'confucius', 'buddha'], ['Nicomachean Ethics', 'Groundwork of the Metaphysics of Morals', 'Utilitarianism', 'Analects']),
  ],
  'analytic-philosophy': [
    section('category', 'A disputed name for a changing tradition', [
      'Analytic philosophy is a varied historical tradition and institutional formation, not one doctrine or technique. Its members have defended incompatible views about language, mind, science, metaphysics, ethics, politics, and philosophy itself. Some prize formal proof, others ordinary usage, conceptual distinction, empirical continuity, historical interpretation, or construction of better concepts. Precision and explicit argument are recurring aspirations, but they do not uniquely identify the tradition, and work described as analytic can be obscure, sweeping, literary, political, or historically engaged.',
      'Definitions by method, topic, style, geography, language, or doctrine all encounter counterexamples. Logical analysis was pivotal in several origin stories, yet much contemporary work uses no formal logic. The tradition grew strongly in Britain and the United States but has major Central European sources and now extends through institutions worldwide. A family-resemblance account captures overlapping features without requiring one essence. A genealogical account emphasizes lines of teaching, criticism, journals, departments, and canon formation. Self-identification also matters, though it can reproduce institutional boundaries rather than explain them.',
      'The category is therefore both descriptive and contested. Calling a work “analytic” can locate it within conversations, audiences, and standards, but it can also function as an honorific meaning rigorous philosophy, unfairly denying rigor to others. A responsible history separates at least four things: philosophical innovations, stories later told about origins, institutions that reproduced a canon, and actual disagreement among the people included. No universally accepted starting point or founder settles the matter. The tradition is best approached as a changing argument about what philosophical clarity and progress require.',
    ], ['analytic-philosophy'], [], []),
    section('contexts', 'Logic, idealism, science, and several origin stories', [
      'Late nineteenth-century transformations in mathematics, logic, psychology, and the sciences created problems that older classifications could not easily contain. Gottlob Frege developed a powerful quantificational logic while pursuing the foundations of arithmetic and opposing psychologistic accounts of logic. His distinctions among object and concept, sense and reference, and the contribution of a sentence’s parts shaped later philosophy of language. Frege did not establish a ready-made movement called analytic philosophy, and his influence was mediated through selective reception, translation, and later reconstruction.',
      'In Britain, Bertrand Russell and G. E. Moore broke with forms of idealism influential at Cambridge. Their revolt was not simply common sense defeating obscurity. British idealists themselves differed, and Russell’s and Moore’s projects soon diverged. Moore used close argument, conceptual distinction, and defenses of ordinary conviction; Russell combined logic, mathematics, epistemology, metaphysics, and public political writing. Historians disagree over whether Frege, Moore, Russell, or a broader network should anchor the origin story. “Founder” language conceals this plurality and makes later developments look inevitable.',
      'Analysis also has histories far older and wider than the twentieth-century tradition. Ancient Greek, Indian, Chinese, and medieval thinkers developed rigorous methods for definition, inference, grammar, language, and conceptual division. Recognizing these does not make every rigorous tradition part of modern Western analytic philosophy. It prevents a different mistake: treating analysis itself as a European invention of Frege or Russell. The specific tradition arose through particular European lineages and institutions, while the activity of analyzing arguments and concepts has no single cultural owner.',
    ], ['logic', 'philosophy-of-language'], ['frege', 'russell', 'g-e-moore'], ['Begriffsschrift', 'On Sense and Reference', 'On Denoting']),
    section('early-analysis', 'Logical form, constructions, and atomism', [
      'Frege’s logic represented multiple quantification and relations more effectively than traditional syllogistic forms. His account of sense and reference helped explain how two expressions can identify the same object while presenting it differently. Russell’s theory of descriptions then showed how a sentence containing an apparently referring phrase could be analyzed without assuming a corresponding object. The achievement was methodological as well as technical: surface grammar might conceal the structure relevant to truth and inference, so philosophical puzzles could be transformed by logical reconstruction.',
      'Russell’s logical atomism and the early Wittgenstein’s Tractatus connected the analysis of propositions with a world conceived as structured by facts. Their views were neither identical nor stable. Russell’s lectures and writings changed across periods; the Tractatus combined austere logical architecture with an account of the limits of meaningful saying and the ethical significance of what it treated as unsayable. Later textbook narratives sometimes reduce both projects to the slogan that language pictures reality, missing disputes about objects, simplicity, acquaintance, logic, and the purpose of philosophy.',
      'Analysis promised genuine discoveries, but it also generated a paradox: if an analysis merely repeats what a concept already means, how can it be informative; if it adds something, in what sense is it the same concept? Moore’s analyses, Russell’s paraphrases, Carnapian explication, later conceptual analysis, and contemporary conceptual engineering answer differently. Some decompose a concept, some reveal logical structure, some replace an imprecise expression with a better tool, and some dissolve a misleading question. The tradition never possessed a single uncontested analytic method even during its supposedly unified early phase.',
    ], ['logic', 'philosophy-of-language', 'metaphysics'], ['frege', 'russell', 'wittgenstein'], ['On Denoting', 'Tractatus Logico-Philosophicus']),
    section('logical-empiricism', 'The Vienna Circle and philosophy of science', [
      'The Vienna Circle and related logical empiricists brought modern logic into renewed empiricism and philosophy of science. Figures including Moritz Schlick, Rudolf Carnap, Otto Neurath, and others disagreed about protocol statements, physicalism, probability, unity of science, and the role of conventions. Verificationist proposals connected meaningful factual claims to possible empirical confirmation, while analytic truths were treated through linguistic or logical rules. The movement’s anti-metaphysical rhetoric was influential, but its projects changed over time and cannot be represented by one crude principle.',
      'Logical empiricism was also institutional and political. Members organized public education, collaborated across sciences, and responded to the crises of interwar Central Europe. Nazism, antisemitism, political persecution, exile, and murder shattered its settings and redirected its development, especially in Britain and North America. Presenting the movement as politically neutral logical housekeeping erases these histories. At the same time, political commitments did not generate one shared philosophy; Neurath’s social and economic concerns, Carnap’s logical frameworks, and other projects must be distinguished.',
      'Strong verification criteria struggled with universal laws, theoretical entities, dispositional claims, ethics, and their own status. Later accounts of confirmation and scientific theories became more flexible, while Popper, Quine, Kuhn, and others challenged different assumptions. Failure of a strict program did not make the movement a detour. It transformed philosophy of science, probability, explanation, formal semantics, and expectations about collaboration with scientific practice. Recent scholarship has recovered internal variety obscured by stories in which a monolithic positivism exists merely to be defeated.',
    ], ['philosophy-of-science', 'logic'], ['carnap', 'quine', 'popper', 'kuhn'], []),
    section('ordinary-language', 'Wittgenstein, ordinary language, and philosophical therapy', [
      'The later Wittgenstein rejected important ambitions associated with his earlier work. Philosophical Investigations studies meaning through use, rules, language-games, and forms of life, resisting the demand for one essence shared by every meaningful expression. Philosophical confusion often arises when a word is removed from the practices that give it a role or when one picture is forced across unlike cases. This is not a general ban on theories or a claim that ordinary speakers cannot be mistaken. It is a demand to examine how a problem is produced before building an explanation.',
      'Oxford ordinary-language philosophers such as J. L. Austin and Gilbert Ryle investigated distinctions embedded in what people do with words. Austin’s work on speech acts showed that utterances can promise, warn, name, excuse, and alter social relations rather than merely describe facts. Ryle criticized a picture of mind as a private object alongside the body. Elizabeth Anscombe’s analysis of intention connected philosophy of action to ethics and the first-person perspective. These projects differed in aim and should not be collapsed into dictionary worship.',
      'Ordinary language can preserve practical distinctions overlooked by a formal model, but it can also carry prejudice, ideology, and historical contingency. Feminist philosophy of language and work on race, disability, and social power show that ordinary usage may enact subordination or distribute authority unequally. Contemporary descendants therefore combine close attention to use with criticism and conceptual revision. The lesson is not that existing language is final. It is that replacing a concept responsibly requires understanding the practices, relationships, and power it already organizes.',
    ], ['philosophy-of-language', 'philosophy-of-mind', 'feminist-philosophy'], ['wittgenstein', 'anscombe'], ['Philosophical Investigations', 'Intention']),
    section('quine-and-after', 'Quine, naturalism, and broken boundaries', [
      'W. V. O. Quine challenged the analytic-synthetic distinction and reductionist pictures in which each meaningful statement receives confirmation separately from immediate experience. His holistic image treated beliefs as confronting experience in interconnected bodies, while his naturalism placed philosophy in continuity with empirical science rather than above it as a first foundation. Quine’s arguments did not end disputes about analyticity, meaning, normativity, or the a priori. Carnapian, post-Quinean, and other responses continue to disagree about language choice and philosophical method.',
      'Wilfrid Sellars, Donald Davidson, Peter Strawson, and many others reorganized inherited debates in different directions. Philosophy of mind interacted with behaviorism, identity theories, functionalism, cognitive science, and revived questions about consciousness. Philosophy of language developed formal semantics, theories of reference, pragmatics, and accounts of communication. Philosophy of science moved beyond a single confirmation program toward realism and antirealism, models, explanation, values, experimentation, and historical practice. No one postwar consensus replaced logical empiricism.',
      'Naturalism itself ranges from modest engagement with science to strong claims that philosophical questions should be reconstructed within scientific inquiry. Its critics worry about normativity, first-person knowledge, mathematics, or the authority required to recommend scientific standards. Naturalists answer that philosophy cannot responsibly theorize about cognition while ignoring how cognition works. This methodological dispute recurs across analytic fields and links Quine to pragmatist predecessors and successors. It also undermines the myth that analytic philosophy is necessarily an armchair enterprise.',
    ], ['epistemology', 'philosophy-of-science', 'pragmatism'], ['quine', 'dewey'], ['Two Dogmas of Empiricism']),
    section('modality-metaphysics', 'Modal logic and the return of metaphysics', [
      'Mid-century suspicion of metaphysics did not permanently define analytic philosophy. Developments in modal logic supplied precise systems for reasoning about necessity and possibility, and possible-world semantics made modal structure tractable. Saul Kripke’s work, alongside contributions by many logicians, transformed the formal landscape; his arguments about naming, necessity, and a posteriori knowledge challenged the assumption that necessary truth, a priori knowledge, and analyticity coincide. These changes helped reopen questions about essence, identity, properties, and counterfactual dependence.',
      'Analytic metaphysics expanded into debates about time, causation, composition, grounding, laws, persons, and social categories. Formal clarity can distinguish claims that ordinary phrasing runs together, but technical machinery does not settle which ontology is true. Critics question whether some disputes track reality or merely alternate vocabularies, and whether reliance on intuitions about remote cases yields knowledge. Defenders point to explanatory integration with science, logic, and ordinary commitments. The old contrast between analytic philosophy and metaphysics therefore fails: opposition to certain metaphysical styles was one episode within a tradition that later produced extensive metaphysical systems.',
      'The revival also illustrates why histories should not read backward from current interests. Kripkean semantics and later metaphysics were not inevitable consequences of Frege’s logic. They emerged through work in mathematical logic, language, and earlier modal traditions, including contributions that standard canons often compress. Once new tools existed, philosophers disagreed over their interpretation and reach. A formal framework can enable a field without dictating its metaphysics, just as shared argumentative standards can intensify rather than eliminate substantive conflict.',
    ], ['logic', 'metaphysics', 'philosophy-of-language'], [], []),
    section('normative-social', 'Ethics, politics, race, gender, and social knowledge', [
      'Analytic institutions have never been confined to language and logic. G. E. Moore’s Principia Ethica helped shape twentieth-century metaethics, and later work developed consequentialist, deontological, contractualist, virtue, and reasons-based theories. Anscombe criticized central assumptions of modern moral philosophy; Philippa Foot and Iris Murdoch redirected attention to virtue, perception, and moral psychology. John Rawls’s A Theory of Justice and the debates it provoked made normative political philosophy prominent in many departments. These projects used recognizably analytic arguments while disagreeing about what analysis could accomplish.',
      'Feminist philosophers challenged claims that inherited methods began from a neutral universal standpoint. Work on care, dependency, embodiment, objectification, social construction, epistemic authority, and nonideal theory changed the questions asked in ethics, metaphysics, language, and knowledge. Philosophy of race investigates the metaphysics of racial categories, the operation of racism, identity, language, ignorance, and justice. Social epistemology studies testimony, disagreement, institutions, propaganda, and collective inquiry. These are not external political topics added to an otherwise complete method; they expose assumptions within its models of persons, reasons, and objectivity.',
      'The presence of normative and social work does not prove that analytic philosophy as an institution is politically neutral or uniformly progressive. Earlier canons often excluded women, philosophers of color, and work deemed insufficiently central, and professional gatekeeping shaped which problems counted. Some early figures engaged politics directly, while others defended objectionable hierarchies or benefited from exclusion. Contemporary expansion involves both recovery and innovation. It should not turn neglected thinkers into tokens or imply that one style now contains every philosophical resource needed for criticism.',
    ], ['ethics', 'political-philosophy', 'feminist-philosophy'], ['g-e-moore', 'anscombe', 'rawls', 'iris-murdoch', 'philippa-foot'], ['Principia Ethica', 'A Theory of Justice']),
    section('methods', 'Formal, experimental, conceptual, and historical methods', [
      'Contemporary analytic philosophy uses a toolkit rather than one method. Conceptual analysis tests distinctions and cases; formal philosophy models inference, probability, language, decision, and strategic interaction; naturalistic work engages psychology, biology, linguistics, economics, and other sciences. Experimental philosophy uses surveys, vignettes, corpus studies, and additional empirical methods to investigate philosophical judgments and assumptions. Conceptual engineering asks how inherited concepts might be revised or replaced. Each method has appropriate domains and characteristic risks.',
      'Thought experiments can isolate a principle but may import culturally local intuitions or strip away morally relevant context. Formal models reveal consequences of assumptions but can mistake tractability for importance. Experiments can test generalizations yet inherit measurement and sampling problems. Conceptual engineering can improve social tools while underestimating resistance, uptake, and power. Historical scholarship can recover alternatives and expose contingent assumptions, though it can become antiquarian if disconnected from philosophical questions. Methodological pluralism is strongest when methods check one another rather than compete for ownership of rigor.',
      'Even “clarity” requires interpretation. An argument may be syntactically explicit while its framing hides a contested social ontology; a historically rich argument may be clear without using numbered premises. Charity, precision, scope, and responsiveness to objection are valuable across traditions. Treating surface style as proof of quality encourages professional conformity and lets familiar assumptions pass unexamined. Analytic philosophy’s best methodological inheritance is therefore not a house style but a revisable practice of making commitments visible enough to criticize.',
    ], ['analytic-philosophy', 'logic', 'philosophy-of-science'], [], []),
    section('boundaries', 'Pragmatism, phenomenology, and the continental divide', [
      'Relations with pragmatism are close and contested. Peirce’s logic and theory of inquiry, James’s account of experience, and Dewey’s naturalism influenced debates later housed in analytic departments, while Quine, Sellars, and subsequent naturalists share important pragmatist themes. Yet pragmatism also emphasizes practice, history, democracy, and reconstruction in ways that resist some analytic self-images. Neither tradition should be absorbed into the other. Their overlap shows that intellectual lineages cross the boundaries later used to organize curricula.',
      'Early analytic philosophy and phenomenology also developed from intersecting concerns about logic, meaning, intentionality, and psychologism. Frege and Husserl are often assigned to opposing traditions only retrospectively. Later analytic philosophers engaged phenomenology, existentialism, and hermeneutics on mind, embodiment, perception, action, and interpretation. Conversely, so-called Continental philosophers use close arguments and analyze language, while analytic philosophers write genealogies and study history. Exchange can be critical without pretending that differences of vocabulary, institution, and aim are unreal.',
      'The analytic-continental divide is therefore an unreliable map of philosophical topic, rigor, politics, or geography. “Continental” groups disparate movements partly by what analytic institutions placed outside themselves, while many European philosophers work in analytic traditions. The distinction can still describe training, citation networks, journals, and expectations, but it should not decide in advance which work deserves attention. A useful comparison asks what a method reveals, what it brackets, and how traditions have actually interacted—not which side owns reason or lived experience.',
    ], ['pragmatism', 'phenomenology', 'continental-philosophy'], ['frege', 'husserl', 'quine', 'dewey'], []),
    section('institutions-future', 'Institutions, geography, exclusions, and open questions', [
      'Analytic philosophy became durable through universities, professional societies, journals, conferences, hiring practices, textbooks, and graduate training. Exile from Central Europe helped relocate logical empiricism into new linguistic and academic settings. Later expansion produced strong communities across Europe, Latin America, Asia, Africa, and Australasia, often interacting with local traditions and educational systems. English remains disproportionately powerful in publication, but the category is not simply British or American. Geographic growth can diversify problems while also exporting existing prestige hierarchies.',
      'Canon formation selects exemplary problems and ancestors. Frege, Russell, Moore, and Wittgenstein matter, but a four-man sequence cannot explain the work of Carnap, Neurath, Susan Stebbing, Anscombe, Foot, Murdoch, or many other contributors, much less the institutions that made some visible and others peripheral. Recovery should distinguish philosophical influence from later significance: a thinker can deserve study even if dominant networks ignored them. It should also examine race, class, gender, disability, empire, and access as conditions of professional history rather than treating exclusion as a footnote to pure ideas.',
      'Open questions concern both philosophy and its organization. Does “analytic” still identify a useful tradition, or has it become too broad? Can family resemblance avoid turning the label into praise for whatever its users favor? How should formal, empirical, historical, and cross-traditional work share standards? Which publication and training structures reward genuine clarity rather than recognizable style? The category may persist because it names real lineages and institutions, but its boundaries remain revisable. Understanding it historically makes participation more responsible: inheritance becomes something to examine and transform, not merely claim.',
    ], ['analytic-philosophy'], [], []),
    section('reading', 'How to read the tradition without mistaking a canon for destiny', [
      'Begin with contrasts inside the tradition. Read Frege on sense and reference beside Russell on descriptions to see distinct uses of logical analysis. Compare the early and later Wittgenstein without assuming a simple conversion from error to truth. Study Carnap or Neurath to encounter logical empiricism in its own ambitions before reading Quine’s critique. Add Austin or Anscombe for attention to ordinary action and language, then Kripke for the modal and semantic developments that supported renewed metaphysics.',
      'Next move across subject matter and social standpoint. Moore’s metaethics, Rawls’s political philosophy, Foot’s virtue ethics, feminist epistemology, philosophy of race, social metaphysics, and experimental philosophy reveal different forms of analytic practice. Pair canonical arguments with historical scholarship about their institutions and with work from pragmatism and phenomenology that addresses overlapping problems. The point is not to make one tradition universally inclusive by definition. It is to understand where its tools travel well, where other traditions change the question, and how exchange improves criticism.',
      'Ask of every proposed analysis what it is for. Does it decompose a concept, reveal inferential form, explain usage, remove confusion, model a phenomenon, or redesign a social tool? What evidence would count against it? Which audience and background knowledge does it assume? Finally, ask how the work entered the canon and what alternatives were excluded. These questions preserve what is valuable in demands for explicit argument while resisting a triumphalist history in which analytic philosophy progresses cleanly from logical discovery to comprehensive clarity.',
    ], ['analytic-philosophy', 'logic', 'philosophy-of-language', 'pragmatism', 'phenomenology'], ['frege', 'russell', 'wittgenstein', 'carnap', 'quine', 'anscombe', 'rawls'], ['On Sense and Reference', 'On Denoting', 'Tractatus Logico-Philosophicus', 'Philosophical Investigations', 'Two Dogmas of Empiricism']),
  ],
};
